"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9631],{84300:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Clones the progress bar template and configures it.\\n\\nThe title label starts hidden and is only shown once a title is set. Passing\\n`instanceWrap` parents the bar to it; otherwise the bar is created unparented and\\nyou must parent `bar.root` yourself.","params":[{"name":"color","desc":"Fill color; leaves the template\'s color when nil","lua_type":"Color3?"},{"name":"title","desc":"Title shown above the bar","lua_type":"string?"},{"name":"instanceWrap","desc":"Parent for the bar, also destroyed by [ProgressBar:Destroy]","lua_type":"Instance?"},{"name":"initialProgress","desc":"Starting fill from 0 to 1, applied without tweening","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"ProgressBar"}],"function_type":"static","source":{"line":63,"path":"src/Shared/Class/ProgressBar.luau"}},{"name":"SetColor","desc":"Recolors the fill and its static overlay.","params":[{"name":"color","desc":"","lua_type":"Color3"}],"returns":[],"function_type":"method","source":{"line":116,"path":"src/Shared/Class/ProgressBar.luau"}},{"name":"SetTitle","desc":"Sets the label above the bar and makes it visible. Also renames the root frame to\\n`<title>ProgressBar`, which is handy when inspecting the UI tree.","params":[{"name":"title","desc":"","lua_type":"string"}],"returns":[],"function_type":"method","source":{"line":130,"path":"src/Shared/Class/ProgressBar.luau"}},{"name":"SetProgressText","desc":"Sets the text shown inside the bar, independently of the fill amount.","params":[{"name":"text","desc":"","lua_type":"string"}],"returns":[],"function_type":"method","source":{"line":144,"path":"src/Shared/Class/ProgressBar.luau"}},{"name":"SetProgress","desc":"Fills the bar to `progress`, tweening over 0.2s.\\n\\nThe value is not clamped \u2014 pass something already within 0 to 1. The tween is\\nskipped entirely when the bar is not yet parented into PlayerGui or Workspace, and\\n`forceSet` skips it on demand.","params":[{"name":"progress","desc":"Fill fraction from 0 to 1","lua_type":"number"},{"name":"forceSet","desc":"Snap instead of tweening","lua_type":"boolean?"}],"returns":[],"function_type":"method","source":{"line":161,"path":"src/Shared/Class/ProgressBar.luau"}},{"name":"UpdateProgressAndTime","desc":"Sets both the fill and the in-bar text from a time window, using\\n`Workspace:GetServerTimeNow()` as the clock.\\n\\nProgress is the fraction of the window elapsed, clamped to 0-1, and the text is\\nthe remaining time at a sensible granularity: `2d 4h`, `3h 20m`, or `1m 5s`.\\n\\nThis is a single update, not a subscription \u2014 call it on a loop (a Heartbeat\\nconnection or a one-second timer) to keep the countdown live.","params":[{"name":"startTime","desc":"Server time the window opened","lua_type":"number"},{"name":"endTime","desc":"Server time the window closes","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":195,"path":"src/Shared/Class/ProgressBar.luau"}},{"name":"Destroy","desc":"Removes the bar from the UI.\\n\\n:::caution Destroys the wrapper, not just the bar\\nWhen the bar was constructed with an `instanceWrap`, **that** instance is\\ndestroyed rather than the bar alone \u2014 anything else parented inside it goes too.\\n:::","params":[],"returns":[],"function_type":"method","source":{"line":237,"path":"src/Shared/Class/ProgressBar.luau"}}],"properties":[],"types":[],"name":"ProgressBar","desc":"Wraps the shared `Assets.UI.ProgressBar` template with a small API for filling it,\\nlabelling it, and driving it from a countdown.\\n\\nEach instance clones the template and holds the resolved child GuiObjects, so\\ncallers never touch the template\'s internal structure. Fill changes tween by\\ndefault, but skip the tween while the bar is not in the rendered tree \u2014 an\\noff-screen bar snaps to its value instead of animating from zero when it appears.\\n\\n```lua\\nlocal bar = ProgressBar.new(Color3.fromRGB(0, 170, 255), \\"Building\\", frame, 0)\\n\\nbar:SetProgress(0.5)\\nbar:Destroy()\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":22,"path":"src/Shared/Class/ProgressBar.luau"}}')}}]);